void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;
    const double MAX_ACT = 1e100;
    const double SCALE   = 1e-100;

    // fast activity increment
    activity[var] += var_inc * coeff;

    // handle possible overflow with lazy scaling
    if (activity[var] > MAX_ACT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // keep VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
